select * from ( SELECT null as issuePartyId, CAVS.ASSET_CODE as assetCode, CAVS.VAL_DATE as valDate, CAVS.UNIT_VAL_NET as unitValNet, CAVS.UNIT_VAL_TOTAL as unitValTotal, CAVS.ORG_CODE as orgCode, CAVS.DEPT_CODE as deptCode, CAVS.CREATE_USER as createUser, CAVS.CREATE_TIME as createTime, CAVS.UPDATE_USER as updateUser, CAVS.UPDATE_TIME as updateTime, CAVS.CHB_SUBMIT_DEADLINE as chbSubmitDeadline, CAVS.SUBMIT_DEADLINE as submitDeadline, nvl(CS.SEND_STATUS,'01') as sendStatus, CS.SUBMIT_TIME as submitTime, CAVS.REGIST_SEQNO registSeqno, CAVS.REMARK as remark, CAVS.STATUS_DATE as statusDate, CAVS.STATUS as status, CS.SUBMIT_FEEDBACK_STATUS as submitFeedbackStatus FROM CHB_AST_VAL_SUB CAVS LEFT JOIN FIN_PRODUCT F ON CAVS.ASSET_CODE=F.FINPROD_MARKET_ID LEFT JOIN TRD_PRODUCT_DEAL_ADD PDD ON CAVS.ASSET_CODE = PDD.TRADE_ID LEFT JOIN CHB_ASSET_SUB_STATUS CS ON CAVS.REGIST_SEQNO=CS.REGIST_SEQNO AND CS.ASSET_TYPE='02'
#{code,jdbcType=VARCHAR}
1=1 /***用金融标的表的交易场所字段来区分是否是公共资产还是私有资产 leipeng 20200711**/ AND F.TRADE_MARKET IS NOT NULL
/**产品投资交易数据筛选产品交易数据*/ and EXISTS ( SELECT 1 FROM CHB_INVEST_TRADE T LEFT JOIN FIN_PRODUCT F ON t.PROD_ID=F.FINPROD_MARKET_ID LEFT JOIN DATA_AUTH_NOTIFY_INST DA ON f.finprod_id=dA.business_id and dA.model_type = '02' and DA.DATA_TYPE='FINPROD04' WHERE CAVS.ASSET_CODE=T.ASSET_CODE
#{code,jdbcType=VARCHAR}
)
1=1
and trim(CAVS.REGIST_SEQNO) = #{regist.registSeqno}
and (CS.SEND_STATUS = #{regist.sendStatus} or CS.SEND_STATUS is null)
and CAVS.REGIST_BANK_CODE = #{regist.registBankCode}
union all
SELECT CC.REGIST_BANK_CODE as issuePartyId, CAVS.ASSET_CODE as assetCode, CAVS.VAL_DATE as valDate, CAVS.UNIT_VAL_NET as unitValNet, CAVS.UNIT_VAL_TOTAL as unitValTotal, CC.REGIST_BANK_CODE as orgCode, CAVS.DEPT_CODE as deptCode, CAVS.CREATE_USER as createUser, CAVS.CREATE_TIME as createTime, CAVS.UPDATE_USER as updateUser, CAVS.UPDATE_TIME as updateTime, CAVS.CHB_SUBMIT_DEADLINE as chbSubmitDeadline, CAVS.SUBMIT_DEADLINE as submitDeadline, nvl(CS.SEND_STATUS,'01') as sendStatus, CS.SUBMIT_TIME as submitTime, CAVS.REGIST_SEQNO registSeqno, CAVS.REMARK as remark, CAVS.STATUS_DATE as statusDate, CAVS.STATUS as status, CS.SUBMIT_FEEDBACK_STATUS as submitFeedbackStatus FROM CHB_AST_VAL_SUB CAVS LEFT JOIN FIN_PRODUCT F ON CAVS.ASSET_CODE=F.FINPROD_MARKET_ID LEFT JOIN TRD_PRODUCT_DEAL_ADD PDD ON CAVS.ASSET_CODE = PDD.TRADE_ID LEFT JOIN DATA_AUTH_NOTIFY_INST DA ON (((DA.BUSINESS_ID = F.FINPROD_ID OR CAVS.ASSET_CODE = DA.BUSINESS_ID ) AND da.data_type != 'PTL01' and da.MODEL_TYPE = '02') or (DA.BUSINESS_ID = PDD.PORTFOLIO_ID AND DA.DATA_TYPE = 'PTL01' and da.MODEL_TYPE = '02')) LEFT JOIN CHB_ORG_REGIST_BANK_CODE CC ON da.BELONG_INSTITUTION_CODE=cc.org_code LEFT JOIN CHB_ASSET_SUB_STATUS CS ON CAVS.REGIST_SEQNO=CS.REGIST_SEQNO AND DA.BELONG_INSTITUTION_CODE=CS.INSTITUTION_CODE AND CS.ASSET_TYPE='02'
1=1 /***用金融标的表的交易场所字段来区分是否是公共资产还是私有资产 leipeng 20200711**/ AND F.TRADE_MARKET IS NULL
1=1
and trim(CAVS.REGIST_SEQNO) = #{regist.registSeqno}
and (CS.SEND_STATUS = #{regist.sendStatus} or CS.SEND_STATUS is null)
and CAVS.REGIST_BANK_CODE = #{regist.registBankCode}
#{code,jdbcType=VARCHAR}
)

