mapper.select:
   	select REGIST_SEQNO
      from CHB_AST_VAL_SUB
      where 

      SEND_STATUS in ('02','03')


      SEND_STATUS = '01'


      ASSET_CODE = #{item.assetCode}
	and VAL_DATE = #{item.valDate}
  	and REGIST_SEQNO != #{item.registSeqno}

   	select SU.REGIST_SEQNO
      FROM CHB_AST_VAL_SUB su
      left join CHB_ASSET_SUB_STATUS cs on su.regist_seqno=cs.regist_seqno and cs.asset_type='02' 
      where 


      	CS.SEND_STATUS in ('02','03')


      	CS.SEND_STATUS = '01' or CS.SEND_STATUS is null


      AND cs.institution_code = #{orgCode,jdbcType=VARCHAR}

	      SU.ASSET_CODE = #{item.assetCode}
		and SU.VAL_DATE = #{item.valDate}
		and SU.REGIST_SEQNO != #{item.registSeqno}
